// Madd lāzim in ٱلضَّآلِّينَ: six counts, lit one by one while on screen.
const BEADS = 6;

const TasmiFeature = () => {
    const { t, i18n } = useTranslation('home');
    const lang = i18n.resolvedLanguage || 'en';
    const rtlScript = lang === 'ar' || lang === 'ur';
    const ref = useRef(null);
    const [seen, setSeen] = useState(false);
    const [still, setStill] = useState(false);
    const [k, setK] = useState(0);

    useEffect(() => {
        if (!document.querySelector(`link[href="${FONTS}"]`)) {
            const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = FONTS; document.head.appendChild(l);
        }
        if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) { setStill(true); return undefined; }
        const el = ref.current;
        if (!el || !('IntersectionObserver' in window)) { setSeen(true); return undefined; }
        const io = new IntersectionObserver(([e]) => setSeen(e.isIntersecting), { threshold: 0.1 });
        io.observe(el);
        return () => io.disconnect();
    }, []);

    useEffect(() => {
        const href = SCRIPT_FONTS[lang];
        if (href && !document.querySelector(`link[href="${href}"]`)) {
            const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = href; document.head.appendChild(l);
        }
    }, [lang]);

    // One word every 650 ms while on screen; a pause at the end, then again.
    useEffect(() => {
        if (!seen || still) return undefined;
        const id = setInterval(() => setK((n) => (n >= TOTAL + 4 ? 0 : n + 1)), 650);
        return () => clearInterval(id);
    }, [seen, still]);

    const points = t('tasmiFeature.points', { returnObjects: true });
    const muPoints = t('tasmiFeature.muPoints', { returnObjects: true });
    const beads = still ? BEADS : k % (BEADS + 3);
    let i = 0;
    return (
        <section ref={ref} className={`tsf${seen ? ' seen' : ''}${still ? ' still' : ''}`} lang={lang} aria-labelledby="tsf-title">
            <style>{css}</style>
            <GoldDefs />
            <div className="border" aria-hidden="true" />
            <div className="wrap">
                <header className="head">
                    <Shamsa />
                    <span className="eyebrow">{rtlScript ? <span className="ar" lang="ar">تَسْمِيع · ٱلْمُعَلِّم</span> : <>{t('tasmiFeature.eyebrow')} <span className="ar" lang="ar">تَسْمِيع</span></>}</span>
                    <h2 id="tsf-title">{t('tasmiFeature.titleA')} <em>{t('tasmiFeature.titleB')}</em></h2>
                    <div className="orn" aria-hidden="true"><i /><Star size={18} /><i /></div>
                    <p className="lede">{t('tasmiFeature.lede')}</p>
                </header>

                <div className="mv">
                    <div>
                        <span className="label"><span className="n">١</span>{t('tasmiFeature.one')}</span>
                        <ul>{Array.isArray(points) && points.map(([b, d]) => <li key={b}><Star size={22} /><div><b>{b}</b><br /><span>{d}</span></div></li>)}</ul>
                    </div>
                    <figure className="mushaf" aria-label={t('tasmiFeature.mushafLabel')}>
                        <div className="page">
                            <div className="frame">
                                <Corner className="tl" /><Corner className="tr" /><Corner className="bl" /><Corner className="br" />
                                <div className="sname" lang="ar"><Cartouche /><span>سُورَةُ ٱلْفَاتِحَةِ</span></div>
                                <p className="text" lang="ar" dir="rtl" style={{ margin: 0 }}>
                                    {FATIHAH.map((ayah, a) => (
                                        <React.Fragment key={a}>
                                            {ayah.map((w) => {
                                                const n = i++;
                                                const cls = still || n < k ? 'w done' : n === k ? 'w now' : 'w';
                                                return <React.Fragment key={n}><span className={cls}>{w}</span> </React.Fragment>;
                                            })}
                                            <span className="num">{ayahNo(a + 1)}</span>{' '}
                                        </React.Fragment>
                                    ))}
                                </p>
                            </div>
                        </div>
                        <figcaption className="listen" aria-hidden="true">
                            {!still && <span className="wave">{[0, 0.15, 0.3, 0.45, 0.6].map((d) => <i key={d} style={{ animationDelay: `${d}s` }} />)}</span>}
                            {t('tasmiFeature.listening')}
                        </figcaption>
                    </figure>
                </div>

                <Divider />

                <div className="mv two">
                    <div>
                        <span className="label"><span className="n">٢</span>{t('tasmiFeature.two')}</span>
                        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 18 }}>
                            <span className="chip">{t('tasmiFeature.experimental')}</span><span className="chip soft">{t('tasmiFeature.coming')}</span>
                        </div>
                        <h3>{t('tasmiFeature.muTitleA')} <em>{t('tasmiFeature.muTitleB')}</em></h3>
                        <p className="lede" style={{ margin: '16px 0 0' }}>{t('tasmiFeature.muLede')}</p>
                        <ul>{Array.isArray(muPoints) && muPoints.map((p) => <li key={p}><Star size={22} /><div><b>{p}</b></div></li>)}</ul>
                    </div>
                    <figure className="lamp" style={{ margin: 0 }} aria-label={t('tasmiFeature.beadsLabel')}>
                        <div className="inner">
                            <div className="arcw">
                                <svg className="arc" viewBox="0 0 200 70" preserveAspectRatio="none" aria-hidden="true">
                                    <path d="M10 64C40 6 160 6 190 64" fill="none" stroke="url(#tsf-g)" strokeWidth="3" strokeLinecap="round" />
                                    <path d="M24 64C52 20 148 20 176 64" fill="none" stroke="url(#tsf-g)" strokeWidth="1" opacity=".6" />
                                </svg>
                                <div className="word" lang="ar">وَلَا ٱل<b>ضَّآ</b>لِّينَ</div>
                            </div>
                            <div className="beads" aria-hidden="true">{Array.from({ length: BEADS }, (_, n) => <i key={n} className={`bead${n < beads ? ' on' : ''}`} />)}</div>
                            <div className="madd">{t('tasmiFeature.madd')}</div>
                        </div>
                    </figure>
                </div>

                <div className="ctas">
                    <RouterLink className="btn gold" to="/tasmi">{t('tasmiFeature.cta')}</RouterLink>
                    <a className="btn ghost" href={APP_STORE} target="_blank" rel="noopener noreferrer">{t('tasmiFeature.appStore')}</a>
                    <a className="btn ghost" href={PLAY} target="_blank" rel="noopener noreferrer">{t('tasmiFeature.play')}</a>
                </div>
            </div>
            <div className="border" aria-hidden="true" />
        </section>
    );
};

export default TasmiFeature;
